# Validate reconstructed CP26 NK-panel outputs.
source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R")); rp_install_and_load(c("dplyr","readr","tibble")); source(file.path(sd_repo_root(),"R","panels","CP26","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP26"); out<-file.path(a,"validation"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
q<-readr::read_csv(file.path(a,"02_feature_extraction","SDY2583_CP26_feature_extraction_summary_STEP2_NK_panel_RECONSTRUCTED.csv"),show_col_types=FALSE); m<-readr::read_csv(file.path(a,"04_metadata_merge_age_QC","SDY2583_CP26_metadata_age_QC_summary_RECONSTRUCTED.csv"),show_col_types=FALSE); st<-readr::read_csv(file.path(a,"05_statistics_age_sex_adjusted","SDY2583_CP26_age_sex_adjusted_statistics_STEP3B_RECONSTRUCTED.csv"),show_col_types=FALSE); sc<-readr::read_csv(file.path(a,"06_composite_scores","SDY2583_CP26_composite_score_statistics_STEP4_RECONSTRUCTED.csv"),show_col_types=FALSE); mt<-readr::read_csv(file.path(a,"07_age_sensitivity_matching_interaction","SDY2583_CP26_matching_summary_STEP4B_RECONSTRUCTED.csv"),show_col_types=FALSE); tc<-readr::read_csv(file.path(a,"12_threshold_sensitivity","SDY2583_CP26_threshold_sensitivity_robustness_counts_STEP5_RECONSTRUCTED.csv"),show_col_types=FALSE)
near<-function(x,y,t=.02)is.finite(x)&&abs(x-y)<=t*max(1,abs(y)); count_class<-function(x){z<-tc$n_variables[tc$robust_class==x];if(length(z))z[1]else 0}
checks<-tibble::tribble(~check,~observed,~expected,~pass,"files",q$n_files[1],850,q$n_files[1]==850,"success",q$n_success[1],850,q$n_success[1]==850,"median total",q$median_total_events[1],299279.5,near(q$median_total_events[1],299279.5,.001),"median CD45 dump-low",q$median_cd45_dump_low_events[1],3839,near(q$median_cd45_dump_low_events[1],3839,.001),"median NK-like",q$median_nk_like_events[1],3505,near(q$median_nk_like_events[1],3505,.001),"valid ages",m$n_valid_age[1],832,m$n_valid_age[1]==832,"feature count",nrow(st),15,nrow(st)==15,"5y pairs",mt$n_pairs[mt$caliper_years==5][1],263,mt$n_pairs[mt$caliper_years==5][1]==263,"10y pairs",mt$n_pairs[mt$caliper_years==10][1],272,mt$n_pairs[mt$caliper_years==10][1]==272,"integrated beta",sc$beta_cancer_vs_healthy[sc$score==CP26_MANIFEST$integrated_score][1],CP26_MANIFEST$benchmarks$integrated_beta,near(sc$beta_cancer_vs_healthy[sc$score==CP26_MANIFEST$integrated_score][1],CP26_MANIFEST$benchmarks$integrated_beta,.01),"threshold robust",count_class("direction_and_FDR_preserved_all_sets"),10,count_class("direction_and_FDR_preserved_all_sets")==10,"threshold direction only",count_class("direction_preserved_FDR_not_all_sets"),7,count_class("direction_preserved_FDR_not_all_sets")==7,"threshold unstable",count_class("direction_not_preserved"),3,count_class("direction_not_preserved")==3)
ref<-path.expand(Sys.getenv("SDY2583_CP26_REFERENCE_DIR",unset="")); if(nzchar(ref)&&dir.exists(ref)){pairs<-list(c(file.path(a,"02_feature_extraction","SDY2583_CP26_FULL_850_feature_table_STEP2_NK_panel_RECONSTRUCTED.csv"),"SDY2583_CP26_FULL_850_feature_table_STEP2_NK_panel_REPAIRED.csv","subject_id"),c(file.path(a,"05_statistics_age_sex_adjusted","SDY2583_CP26_age_sex_adjusted_statistics_STEP3B_RECONSTRUCTED.csv"),"SDY2583_CP26_age_sex_adjusted_statistics_STEP3B.csv","module,feature"),c(file.path(a,"06_composite_scores","SDY2583_CP26_composite_score_statistics_STEP4_RECONSTRUCTED.csv"),"SDY2583_CP26_composite_score_statistics_STEP4.csv","score")); for(p in pairs){hit<-list.files(ref,p[2],full.names=TRUE,recursive=TRUE,fixed=TRUE); cmp<-if(length(hit))rp_compare_csv(p[1],hit[1],strsplit(p[3],",",fixed=TRUE)[[1]])else tibble::tibble(pass=FALSE,detail="reference missing"); checks<-dplyr::bind_rows(checks,tibble::tibble(check=p[2],observed=cmp$detail[1],expected="table match",pass=cmp$pass[1]))}}
readr::write_csv(checks,file.path(out,"SDY2583_CP26_reconstruction_validation_report.csv")); print(checks,n=nrow(checks)); if(any(!checks$pass))stop("CP26 validation failed.")
